  if(f.error!=NULL){Bytes ram=base_ram(f.puts);State s=state_of(f.regs,f.entry,f.carry);fails_at(ram,s,f.fail,f.error);++error_count;if(f.fail!=f.entry)++moved_fail;continue;}
